mapper.select:
/* 펫 카드 - 회원 헤더 */
SELECT
  m.mbr_nknm,
  m.mbr_profile
FROM member m
WHERE m.mbr_cd = #{mbrCd}

/* 펫 카드 - 태그 */
SELECT t.tag_nm
FROM dog_tag dt
JOIN tag t ON t.tag_id = dt.tag_id
WHERE dt.card_id = #{cardId}
ORDER BY t.tag_nm ASC

/* 카드 소유자 mbr_cd */
SELECT pc.mbr_cd
FROM profile_card pc
WHERE pc.card_id = #{cardId}

mapper.update:
        /* 펫 카드 - 이미지 URL 갱신 */
        UPDATE pet p
	    JOIN profile_card pc ON pc.pet_cd = p.pet_cd
	    SET p.pet_profile_img_url = #{url}
	    WHERE pc.card_id = #{cardId}

/* 펫 카드 - 소개 갱신 */
UPDATE profile_card
SET card_cn = #{intro}
WHERE card_id = #{cardId}

mapper.select:
/* 태그명 → 태그ID */
SELECT t.tag_id
FROM tag t
WHERE t.tag_nm IN

    #{nm}

ORDER BY t.tag_nm ASC

mapper.delete:
/* 카드-태그 매핑 삭제 */
DELETE FROM dog_tag
WHERE card_id = #{cardId}

